-- DIBUAT OTOMATIS oleh `pnpm seed:items` dari data/items.json dan data/rule-sets/*.json. Jangan disunting manual.
-- Aturan klasifikasi: upsert. Tes: dibuat sekali per (nama, versi); butir hanya ditambahkan bila tes belum dibekukan.

insert into public.rule_sets (rule_set_id, name, version, kind, rules, confidence_mode, incomplete_category, is_default) values
  ('default-v1', 'default-v1', 1, 'combined', '[{"A":true,"R":true,"C":true,"category":"SC"},{"A":true,"R":true,"C":false,"category":"LC"},{"A":true,"R":false,"C":true,"category":"E"},{"A":false,"R":true,"C":true,"category":"E"},{"A":false,"R":false,"C":true,"category":"M"},{"A":true,"R":false,"C":false,"category":"LK"},{"A":false,"R":true,"C":false,"category":"LK"},{"A":false,"R":false,"C":false,"category":"LK"}]'::jsonb, 'all_tiers_at_or_above_threshold', null, false),
  ('pedoman-v1', 'pedoman-v1', 1, 'per_tier', '[{"no":1,"A":true,"R":true,"CA":true,"CR":true,"category":"SC"},{"no":2,"A":true,"R":true,"CA":true,"CR":false,"category":"LC"},{"no":3,"A":true,"R":true,"CA":false,"CR":true,"category":"LC"},{"no":4,"A":true,"R":true,"CA":false,"CR":false,"category":"LC"},{"no":5,"A":true,"R":false,"CA":true,"CR":true,"category":"M"},{"no":6,"A":false,"R":true,"CA":true,"CR":true,"category":"M"},{"no":7,"A":false,"R":false,"CA":true,"CR":true,"category":"M"},{"no":8,"A":true,"R":false,"CA":false,"CR":false,"category":"LK"},{"no":9,"A":false,"R":true,"CA":false,"CR":false,"category":"LK"},{"no":10,"A":false,"R":false,"CA":false,"CR":false,"category":"LK"},{"no":11,"A":true,"R":false,"CA":true,"CR":false,"category":"E"},{"no":12,"A":true,"R":false,"CA":false,"CR":true,"category":"E"},{"no":13,"A":false,"R":true,"CA":true,"CR":false,"category":"E"},{"no":14,"A":false,"R":true,"CA":false,"CR":true,"category":"E"},{"no":15,"A":false,"R":false,"CA":true,"CR":false,"category":"E"},{"no":16,"A":false,"R":false,"CA":false,"CR":true,"category":"E"}]'::jsonb, null, 'E', true)
on conflict (rule_set_id) do update set kind = excluded.kind, rules = excluded.rules,
  confidence_mode = excluded.confidence_mode, incomplete_category = excluded.incomplete_category, is_default = excluded.is_default;

insert into public.tests (name, version, status, rule_set_id)
select 'Tes diagnostik four-tier tata surya', 1, 'active', id from public.rule_sets where rule_set_id = 'pedoman-v1'
on conflict (name, version) do nothing;

-- Hanya versi terbaru yang aktif.
update public.tests set status = 'archived' where name = 'Tes diagnostik four-tier tata surya' and version < 1 and status = 'active';

insert into public.test_items (test_id, item_order, content, concept_domain, report_domain, misconception_code, fixed_order)
select t.id, v.item_order, v.content, v.concept_domain, v.report_domain, v.misconception_code, v.fixed_order
from public.tests t, (values
  (1, '{"stem":"Matahari termasuk jenis benda langit ….","stem_image":null,"format":"four_tier_standard","tier1":{"options":[{"key":"A","text":"planet"},{"key":"B","text":"satelit"},{"key":"C","text":"bintang"},{"key":"D","text":"komet"}],"correct":"C","fixed_order":false},"reason":{"options":[{"key":"A","text":"Matahari adalah benda langit terbesar dalam tata surya.","maps_to_misconception":null},{"key":"B","text":"Matahari memancarkan cahaya dan panasnya sendiri.","maps_to_misconception":null},{"key":"C","text":"Matahari bergerak mengelilingi Bumi setiap hari.","maps_to_misconception":null},{"key":"D","text":"Bintang hanya tampak pada malam hari, sedangkan Matahari tampak pada siang hari.","maps_to_misconception":null}],"correct":"B"},"confidence":{"levels":["Yakin","Tidak yakin"],"threshold_index":0},"concept_domain":"benda_langit","report_domain":"benda_langit","misconception_target":"MK-B01"}'::jsonb, 'benda_langit', 'benda_langit', 'MK-B01', false),
  (2, '{"stem":"Bulan termasuk jenis benda langit ….","stem_image":null,"format":"four_tier_standard","tier1":{"options":[{"key":"A","text":"planet"},{"key":"B","text":"satelit alami"},{"key":"C","text":"bintang"},{"key":"D","text":"asteroid"}],"correct":"B","fixed_order":false},"reason":{"options":[{"key":"A","text":"Bulan beredar mengelilingi Matahari secara langsung seperti Bumi.","maps_to_misconception":null},{"key":"B","text":"Bulan memancarkan cahayanya sendiri pada malam hari.","maps_to_misconception":null},{"key":"C","text":"Bulan beredar mengelilingi planet Bumi.","maps_to_misconception":null},{"key":"D","text":"Bulan berbentuk bulat dan berukuran besar.","maps_to_misconception":null}],"correct":"C"},"confidence":{"levels":["Yakin","Tidak yakin"],"threshold_index":0},"concept_domain":"benda_langit","report_domain":"benda_langit","misconception_target":"MK-B02"}'::jsonb, 'benda_langit', 'benda_langit', 'MK-B02', false),
  (3, '{"stem":"Ketika sebuah komet mendekati Matahari, ekornya akan terlihat ….","stem_image":null,"format":"four_tier_standard","tier1":{"options":[{"key":"A","text":"selalu berada di belakang arah gerak komet"},{"key":"B","text":"mengarah ke Matahari"},{"key":"C","text":"selalu menjauhi Matahari"},{"key":"D","text":"hilang karena terbakar Matahari"}],"correct":"C","fixed_order":false},"reason":{"options":[{"key":"A","text":"Ekor terbentuk seperti asap kendaraan yang tertinggal di belakang benda yang bergerak cepat.","maps_to_misconception":null},{"key":"B","text":"Gaya tarik Matahari menarik gas dan debu komet ke arah Matahari.","maps_to_misconception":null},{"key":"C","text":"Panas Matahari membakar seluruh es komet sehingga ekornya lenyap.","maps_to_misconception":null},{"key":"D","text":"Angin dan radiasi Matahari mendorong gas dan debu komet menjauhi Matahari.","maps_to_misconception":null}],"correct":"D"},"confidence":{"levels":["Yakin","Tidak yakin"],"threshold_index":0},"concept_domain":"benda_langit","report_domain":"benda_langit","misconception_target":"MK-B03"}'::jsonb, 'benda_langit', 'benda_langit', 'MK-B03', false),
  (4, '{"stem":"Garis cahaya terang yang tampak melintas cepat di langit malam ketika batuan antariksa masuk ke atmosfer Bumi disebut ….","stem_image":null,"format":"four_tier_standard","tier1":{"options":[{"key":"A","text":"meteoroid"},{"key":"B","text":"meteor"},{"key":"C","text":"meteorit"},{"key":"D","text":"bintang jatuh yang padam"}],"correct":"B","fixed_order":false},"reason":{"options":[{"key":"A","text":"Batuan antariksa berpijar karena bergesekan dengan udara di atmosfer Bumi.","maps_to_misconception":null},{"key":"B","text":"Ada bintang yang lepas dari tempatnya lalu jatuh ke arah Bumi.","maps_to_misconception":null},{"key":"C","text":"Batuan itu masih berada di luar angkasa dan belum memasuki atmosfer.","maps_to_misconception":null},{"key":"D","text":"Batuan itu sudah jatuh dan berada di permukaan Bumi.","maps_to_misconception":null}],"correct":"A"},"confidence":{"levels":["Yakin","Tidak yakin"],"threshold_index":0},"concept_domain":"benda_langit","report_domain":"benda_langit","misconception_target":"MK-B04"}'::jsonb, 'benda_langit', 'benda_langit', 'MK-B04', false),
  (5, '{"stem":"Batuan antariksa yang tidak habis terbakar di atmosfer dan akhirnya jatuh sampai ke permukaan Bumi disebut ….","stem_image":null,"format":"four_tier_standard","tier1":{"options":[{"key":"A","text":"meteorit"},{"key":"B","text":"meteor"},{"key":"C","text":"komet"},{"key":"D","text":"asteroid"}],"correct":"A","fixed_order":false},"reason":{"options":[{"key":"A","text":"Semua batuan antariksa pasti sampai ke permukaan Bumi.","maps_to_misconception":null},{"key":"B","text":"Meteorit berasal dari pecahan Bulan yang jatuh ke Bumi.","maps_to_misconception":null},{"key":"C","text":"Sisa batuan yang tidak habis terbakar saat melewati atmosfer jatuh ke permukaan Bumi.","maps_to_misconception":null},{"key":"D","text":"Meteorit adalah bintang yang telah padam lalu jatuh.","maps_to_misconception":null}],"correct":"C"},"confidence":{"levels":["Yakin","Tidak yakin"],"threshold_index":0},"concept_domain":"benda_langit","report_domain":"benda_langit","misconception_target":"MK-B05"}'::jsonb, 'benda_langit', 'benda_langit', 'MK-B05', false),
  (6, '{"stem":"Urutan empat planet terdekat dari Matahari yang benar adalah ….","stem_image":null,"format":"four_tier_standard","tier1":{"options":[{"key":"A","text":"Venus – Merkurius – Bumi – Mars"},{"key":"B","text":"Merkurius – Bumi – Venus – Mars"},{"key":"C","text":"Mars – Bumi – Venus – Merkurius"},{"key":"D","text":"Merkurius – Venus – Bumi – Mars"}],"correct":"D","fixed_order":false},"reason":{"options":[{"key":"A","text":"Planet diurutkan dari yang paling kecil ke yang paling besar.","maps_to_misconception":null},{"key":"B","text":"Planet diurutkan berdasarkan jarak orbitnya dari Matahari.","maps_to_misconception":null},{"key":"C","text":"Planet diurutkan dari yang paling panas ke yang paling dingin.","maps_to_misconception":null},{"key":"D","text":"Planet diurutkan dari yang paling terang di langit malam.","maps_to_misconception":null}],"correct":"B"},"confidence":{"levels":["Yakin","Tidak yakin"],"threshold_index":0},"concept_domain":"planet","report_domain":"planet","misconception_target":"MK-B06"}'::jsonb, 'planet', 'planet', 'MK-B06', false),
  (7, '{"stem":"Planet yang memiliki suhu permukaan paling panas dalam tata surya adalah ….","stem_image":null,"format":"four_tier_standard","tier1":{"options":[{"key":"A","text":"Merkurius"},{"key":"B","text":"Venus"},{"key":"C","text":"Bumi"},{"key":"D","text":"Mars"}],"correct":"B","fixed_order":false},"reason":{"options":[{"key":"A","text":"Planet yang paling dekat dengan Matahari pasti paling panas.","maps_to_misconception":null},{"key":"B","text":"Planet itu tampak paling terang di langit sehingga paling panas.","maps_to_misconception":null},{"key":"C","text":"Atmosfernya yang tebal dan kaya karbon dioksida menimbulkan efek rumah kaca yang memerangkap panas.","maps_to_misconception":null},{"key":"D","text":"Planet itu tidak memiliki atmosfer sehingga panas Matahari langsung mengenai permukaannya.","maps_to_misconception":null}],"correct":"C"},"confidence":{"levels":["Yakin","Tidak yakin"],"threshold_index":0},"concept_domain":"planet","report_domain":"planet","misconception_target":"MK-B07"}'::jsonb, 'planet', 'planet', 'MK-B07', false),
  (8, '{"stem":"Planet terbesar dalam tata surya adalah ….","stem_image":null,"format":"four_tier_standard","tier1":{"options":[{"key":"A","text":"Saturnus"},{"key":"B","text":"Neptunus"},{"key":"C","text":"Jupiter"},{"key":"D","text":"Uranus"}],"correct":"C","fixed_order":false},"reason":{"options":[{"key":"A","text":"Planet yang memiliki cincin paling besar adalah planet terbesar.","maps_to_misconception":null},{"key":"B","text":"Planet itu memiliki diameter dan massa paling besar di antara semua planet.","maps_to_misconception":null},{"key":"C","text":"Semakin jauh dari Matahari, ukuran planet semakin besar.","maps_to_misconception":null},{"key":"D","text":"Planet itu tampak paling besar ketika dilihat dari Bumi.","maps_to_misconception":null}],"correct":"B"},"confidence":{"levels":["Yakin","Tidak yakin"],"threshold_index":0},"concept_domain":"planet","report_domain":"planet","misconception_target":"MK-B08"}'::jsonb, 'planet', 'planet', 'MK-B08', false),
  (9, '{"stem":"Sabuk asteroid dalam tata surya terletak di antara orbit planet ….","stem_image":null,"format":"four_tier_standard","tier1":{"options":[{"key":"A","text":"Bumi dan Mars"},{"key":"B","text":"Mars dan Jupiter"},{"key":"C","text":"Jupiter dan Saturnus"},{"key":"D","text":"Merkurius dan Venus"}],"correct":"B","fixed_order":false},"reason":{"options":[{"key":"A","text":"Asteroid adalah batuan yang mengelilingi Bumi seperti Bulan.","maps_to_misconception":null},{"key":"B","text":"Asteroid berada di luar tata surya, jauh setelah Neptunus.","maps_to_misconception":null},{"key":"C","text":"Asteroid adalah pecahan Bumi yang terlempar ke luar angkasa.","maps_to_misconception":null},{"key":"D","text":"Batuan sisa pembentukan tata surya beredar mengelilingi Matahari di antara kedua planet itu.","maps_to_misconception":null}],"correct":"D"},"confidence":{"levels":["Yakin","Tidak yakin"],"threshold_index":0},"concept_domain":"planet","report_domain":"planet","misconception_target":"MK-B09"}'::jsonb, 'planet', 'planet', 'MK-B09', false),
  (10, '{"stem":"Kelompok planet yang tersusun dari batuan dan memiliki permukaan padat adalah ….","stem_image":null,"format":"four_tier_standard","tier1":{"options":[{"key":"A","text":"Jupiter, Saturnus, Uranus, Neptunus"},{"key":"B","text":"Bumi, Mars, Jupiter, Saturnus"},{"key":"C","text":"semua planet dalam tata surya"},{"key":"D","text":"Merkurius, Venus, Bumi, Mars"}],"correct":"D","fixed_order":false},"reason":{"options":[{"key":"A","text":"Planet yang letaknya jauh dari Matahari membeku sehingga menjadi batuan padat.","maps_to_misconception":null},{"key":"B","text":"Semua planet terbentuk dengan cara yang sama sehingga semuanya berbatu.","maps_to_misconception":null},{"key":"C","text":"Planet yang berukuran besar pasti tersusun dari batuan.","maps_to_misconception":null},{"key":"D","text":"Planet dalam yang dekat dengan Matahari tersusun dari batuan dan logam.","maps_to_misconception":null}],"correct":"D"},"confidence":{"levels":["Yakin","Tidak yakin"],"threshold_index":0},"concept_domain":"planet","report_domain":"planet","misconception_target":"MK-B10"}'::jsonb, 'planet', 'planet', 'MK-B10', false),
  (11, '{"stem":"Terjadinya siang dan malam di Bumi disebabkan oleh ….","stem_image":null,"format":"four_tier_standard","tier1":{"options":[{"key":"A","text":"Matahari bergerak mengelilingi Bumi"},{"key":"B","text":"revolusi Bumi"},{"key":"C","text":"rotasi Bumi"},{"key":"D","text":"Matahari tertutup awan atau gunung"}],"correct":"C","fixed_order":false},"reason":{"options":[{"key":"A","text":"Matahari terbit dan terbenam karena bergerak mengitari Bumi setiap hari.","maps_to_misconception":null},{"key":"B","text":"Bagian Bumi yang menghadap Matahari mengalami siang dan yang membelakangi mengalami malam.","maps_to_misconception":null},{"key":"C","text":"Bumi mengelilingi Matahari satu kali setiap hari.","maps_to_misconception":null},{"key":"D","text":"Pada malam hari Matahari bersembunyi di balik gunung.","maps_to_misconception":null}],"correct":"B"},"confidence":{"levels":["Yakin","Tidak yakin"],"threshold_index":0},"concept_domain":"rotasi_revolusi","report_domain":"rotasi_revolusi","misconception_target":"MK-B11"}'::jsonb, 'rotasi_revolusi', 'rotasi_revolusi', 'MK-B11', false),
  (12, '{"stem":"Waktu yang diperlukan Bumi untuk berotasi satu kali adalah sekitar ….","stem_image":null,"format":"four_tier_standard","tier1":{"options":[{"key":"A","text":"24 jam"},{"key":"B","text":"7 hari"},{"key":"C","text":"30 hari"},{"key":"D","text":"365 hari"}],"correct":"A","fixed_order":false},"reason":{"options":[{"key":"A","text":"Satu kali rotasi sama dengan waktu Bulan mengelilingi Bumi.","maps_to_misconception":null},{"key":"B","text":"Satu kali rotasi sama dengan satu tahun.","maps_to_misconception":null},{"key":"C","text":"Satu kali rotasi menghasilkan satu kali pergantian siang dan malam (satu hari).","maps_to_misconception":null},{"key":"D","text":"Satu kali rotasi sama dengan satu minggu.","maps_to_misconception":null}],"correct":"C"},"confidence":{"levels":["Yakin","Tidak yakin"],"threshold_index":0},"concept_domain":"rotasi_revolusi","report_domain":"rotasi_revolusi","misconception_target":"MK-B12"}'::jsonb, 'rotasi_revolusi', 'rotasi_revolusi', 'MK-B12', false),
  (13, '{"stem":"Matahari tampak terbit di timur dan terbenam di barat karena ….","stem_image":null,"format":"four_tier_standard","tier1":{"options":[{"key":"A","text":"Matahari bergerak dari timur ke barat"},{"key":"B","text":"Bumi berotasi dari timur ke barat"},{"key":"C","text":"Bumi berevolusi mengelilingi Matahari"},{"key":"D","text":"Bumi berotasi dari barat ke timur"}],"correct":"D","fixed_order":false},"reason":{"options":[{"key":"A","text":"Gerak Matahari yang kita lihat adalah gerak semu akibat perputaran Bumi.","maps_to_misconception":null},{"key":"B","text":"Matahari benar-benar berpindah tempat di langit setiap hari.","maps_to_misconception":null},{"key":"C","text":"Arah terbit Matahari sama dengan arah putaran Bumi.","maps_to_misconception":null},{"key":"D","text":"Perpindahan Bumi mengelilingi Matahari membuat Matahari tampak bergerak setiap hari.","maps_to_misconception":null}],"correct":"A"},"confidence":{"levels":["Yakin","Tidak yakin"],"threshold_index":0},"concept_domain":"rotasi_revolusi","report_domain":"rotasi_revolusi","misconception_target":"MK-B13"}'::jsonb, 'rotasi_revolusi', 'rotasi_revolusi', 'MK-B13', false),
  (14, '{"stem":"Pergantian musim di belahan Bumi utara dan selatan terutama disebabkan oleh ….","stem_image":null,"format":"four_tier_standard","tier1":{"options":[{"key":"A","text":"kemiringan sumbu rotasi Bumi selama revolusi"},{"key":"B","text":"perubahan jarak Bumi ke Matahari"},{"key":"C","text":"rotasi Bumi"},{"key":"D","text":"perubahan jumlah awan di langit"}],"correct":"A","fixed_order":false},"reason":{"options":[{"key":"A","text":"Ketika Bumi dekat dengan Matahari terjadi musim panas, ketika jauh terjadi musim dingin.","maps_to_misconception":null},{"key":"B","text":"Bumi berputar pada porosnya sehingga musim berganti setiap hari.","maps_to_misconception":null},{"key":"C","text":"Sumbu Bumi yang miring membuat tiap belahan Bumi bergantian menerima sinar Matahari lebih tegak dan lebih lama.","maps_to_misconception":null},{"key":"D","text":"Awan menghalangi panas Matahari pada musim tertentu.","maps_to_misconception":null}],"correct":"C"},"confidence":{"levels":["Yakin","Tidak yakin"],"threshold_index":0},"concept_domain":"rotasi_revolusi","report_domain":"rotasi_revolusi","misconception_target":"MK-B14"}'::jsonb, 'rotasi_revolusi', 'rotasi_revolusi', 'MK-B14', false),
  (15, '{"stem":"Bumi mengelilingi Matahari satu kali dalam waktu sekitar 365¼ hari. Salah satu akibat dari gerak tersebut adalah ….","stem_image":null,"format":"four_tier_standard","tier1":{"options":[{"key":"A","text":"terjadinya siang dan malam"},{"key":"B","text":"adanya tahun kabisat setiap empat tahun"},{"key":"C","text":"perbedaan waktu antarwilayah"},{"key":"D","text":"terbit dan terbenamnya Matahari"}],"correct":"B","fixed_order":false},"reason":{"options":[{"key":"A","text":"Kelebihan seperempat hari setiap tahun dikumpulkan menjadi satu hari tambahan setiap empat tahun.","maps_to_misconception":null},{"key":"B","text":"Bumi berputar pada porosnya sehingga terjadi pergantian hari.","maps_to_misconception":null},{"key":"C","text":"Bumi berputar sehingga wilayah timur lebih dahulu terkena sinar Matahari.","maps_to_misconception":null},{"key":"D","text":"Matahari mengelilingi Bumi selama satu tahun.","maps_to_misconception":null}],"correct":"A"},"confidence":{"levels":["Yakin","Tidak yakin"],"threshold_index":0},"concept_domain":"rotasi_revolusi","report_domain":"rotasi_revolusi","misconception_target":"MK-B15"}'::jsonb, 'rotasi_revolusi', 'rotasi_revolusi', 'MK-B15', false),
  (16, '{"stem":"Posisi Matahari, Bulan, dan Bumi yang benar saat terjadi gerhana Matahari adalah ….","stem_image":null,"format":"four_tier_standard","tier1":{"options":[{"key":"A","text":"Matahari – Bumi – Bulan"},{"key":"B","text":"Bumi – Matahari – Bulan"},{"key":"C","text":"Matahari – Bulan – Bumi"},{"key":"D","text":"Bulan – Matahari – Bumi"}],"correct":"C","fixed_order":false},"reason":{"options":[{"key":"A","text":"Bumi menghalangi cahaya Matahari sehingga Matahari tidak terlihat.","maps_to_misconception":null},{"key":"B","text":"Bulan berada di antara Matahari dan Bumi sehingga bayangan Bulan jatuh ke permukaan Bumi.","maps_to_misconception":null},{"key":"C","text":"Matahari padam untuk sementara waktu.","maps_to_misconception":null},{"key":"D","text":"Awan tebal menutupi Matahari.","maps_to_misconception":null}],"correct":"B"},"confidence":{"levels":["Yakin","Tidak yakin"],"threshold_index":0},"concept_domain":"gerhana","report_domain":"gerhana","misconception_target":"MK-B16"}'::jsonb, 'gerhana', 'gerhana', 'MK-B16', false),
  (17, '{"stem":"Gerhana Bulan terjadi ketika ….","stem_image":null,"format":"four_tier_standard","tier1":{"options":[{"key":"A","text":"Bulan berada di antara Matahari dan Bumi"},{"key":"B","text":"Matahari berada di antara Bumi dan Bulan"},{"key":"C","text":"Bulan tertutup awan pada malam hari"},{"key":"D","text":"Bumi berada di antara Matahari dan Bulan"}],"correct":"D","fixed_order":false},"reason":{"options":[{"key":"A","text":"Bulan masuk ke dalam bayangan Bumi sehingga tidak mendapat cahaya Matahari.","maps_to_misconception":null},{"key":"B","text":"Bayangan Bulan menutupi Matahari.","maps_to_misconception":null},{"key":"C","text":"Bulan berhenti memancarkan cahayanya sendiri.","maps_to_misconception":null},{"key":"D","text":"Awan menghalangi cahaya Bulan sampai ke Bumi.","maps_to_misconception":null}],"correct":"A"},"confidence":{"levels":["Yakin","Tidak yakin"],"threshold_index":0},"concept_domain":"gerhana","report_domain":"gerhana","misconception_target":"MK-B17"}'::jsonb, 'gerhana', 'gerhana', 'MK-B17', false),
  (18, '{"stem":"Gerhana Bulan hanya mungkin terjadi pada saat fase ….","stem_image":null,"format":"four_tier_standard","tier1":{"options":[{"key":"A","text":"bulan baru"},{"key":"B","text":"bulan sabit"},{"key":"C","text":"bulan purnama"},{"key":"D","text":"bulan separuh"}],"correct":"C","fixed_order":false},"reason":{"options":[{"key":"A","text":"Pada fase ini Bulan tidak tampak sehingga mudah tertutup.","maps_to_misconception":null},{"key":"B","text":"Pada fase ini Bumi berada di antara Matahari dan Bulan.","maps_to_misconception":null},{"key":"C","text":"Pada fase ini Bulan berada paling dekat dengan Matahari.","maps_to_misconception":null},{"key":"D","text":"Pada fase ini sebagian Bulan sudah tertutup bayangan Bumi.","maps_to_misconception":null}],"correct":"B"},"confidence":{"levels":["Yakin","Tidak yakin"],"threshold_index":0},"concept_domain":"gerhana","report_domain":"gerhana","misconception_target":"MK-B18"}'::jsonb, 'gerhana', 'gerhana', 'MK-B18', false),
  (19, '{"stem":"Bulan mengelilingi Bumi sekitar satu kali setiap bulan, tetapi gerhana tidak terjadi setiap bulan. Hal ini karena ….","stem_image":null,"format":"four_tier_standard","tier1":{"options":[{"key":"A","text":"orbit Bulan miring terhadap bidang orbit Bumi"},{"key":"B","text":"Bulan terlalu kecil untuk menutupi Matahari"},{"key":"C","text":"Bulan tidak selalu mengelilingi Bumi"},{"key":"D","text":"gerhana terjadi setiap bulan tetapi tidak terlihat"}],"correct":"A","fixed_order":false},"reason":{"options":[{"key":"A","text":"Bulan kadang berhenti beredar sehingga tidak sejajar dengan Bumi.","maps_to_misconception":null},{"key":"B","text":"Ukuran Bulan berubah-ubah setiap bulan.","maps_to_misconception":null},{"key":"C","text":"Matahari, Bulan, dan Bumi jarang berada tepat pada satu garis lurus karena bidang orbit Bulan miring.","maps_to_misconception":null},{"key":"D","text":"Gerhana selalu terjadi, tetapi terhalang oleh awan.","maps_to_misconception":null}],"correct":"C"},"confidence":{"levels":["Yakin","Tidak yakin"],"threshold_index":0},"concept_domain":"gerhana","report_domain":"gerhana","misconception_target":"MK-B19"}'::jsonb, 'gerhana', 'gerhana', 'MK-B19', false),
